// M12-F3: consumes REAL Android Emulator install-over evidence generated by
// the existing source-backed harness. Not an upload signer or physical phone test.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const base='qa-results/emulator-upgrade';
const read=p=>fs.readFileSync(path.join(base,p),'utf8');
const data=p=>JSON.parse(read(p));
const before=data('webview-before.json');
const baseline=data('webview-baseline-relaunch.json');
const after=data('webview-after.json');
const oldSigner=read('baseline-signer.txt'),newSigner=read('current-signer.txt');
const oldBadging=read('baseline-badging.txt'),newBadging=read('current-badging.txt');
const oldInstall=read('baseline-install.txt'),newInstall=read('current-install.txt');
const recap=read('README.txt');
const installed=read('installed-version.txt');
const pattern=/Signer #1 certificate SHA-256 digest:\s*([0-9A-Fa-f:]+)/;
const digest=s=>{
 const found=pattern.exec(s);
 assert.ok(found,'APK certificate SHA-256 absent from emulator logs');
 return found[1].toLowerCase().replaceAll(':','');
};
const sig=digest(oldSigner);
assert.equal(digest(newSigner),sig,'Mismatch: an Android update must use the same signer');
assert.match(oldBadging,/name='com\.playereden\.ricochetrumble\.preview'/);
assert.match(newBadging,/name='com\.playereden\.ricochetrumble\.preview'/);
assert.match(oldBadging,/versionCode='100041'/);
assert.match(newBadging,/versionCode='100050'/);
assert.match(installed,/versionCode=100050/);
assert.match(oldInstall,/^Success\s*$/m);
assert.match(newInstall,/^Success\s*$/m);
assert.match(recap,/ANDROID_EMULATOR_PACKAGE_UPGRADE_PASS/);
assert.match(recap,/REAL adb install -r, no uninstall\/data clearing: PASS/);
assert.match(recap,/APP-PRIVATE CANARY PERSISTED: YES/);
assert.match(recap,/REAL WEBVIEW 5-SAVE RECORDS \+ DOSSIER UI PERSISTED: YES/);
const savedKeys=['rr-options-v06','rr-custom-v1','rr-custom-presets-v1',
 'rr-dossier-v1','rr-hangar-paint-v1'];
for(const stage of [before,baseline,after]){
 assert.equal(stage.status,'PASS');
 assert.equal(stage.package,'com.playereden.ricochetrumble.preview');
 assert.equal(stage.records,5);
 assert.ok(stage.origin.startsWith('file:///android_asset/index.html'),'real Android WebView origin');
 assert.deepEqual(Object.keys(stage.keys).sort(),savedKeys.slice().sort(),'all five records must be present');
}
for(const key of savedKeys){
 assert.ok(typeof before.keys[key]==='string');
 assert.equal(baseline.keys[key],before.keys[key],'save drift on baseline relaunch '+key);
 assert.equal(after.keys[key],before.keys[key],'save drift on Android package upgrade '+key);
}
for(const stage of [baseline,after]){
 assert.equal(stage.visibleDossier.matches,'6');
 assert.equal(stage.visibleDossier.kos,'11');
}
const report={
 result:'ANDROID_EMULATOR_INSTALL_OVER_PASS_NOT_PHYSICAL_RELEASE_APPROVAL',
 packageId:'com.playereden.ricochetrumble.preview',
 versionCodeFrom:100041,versionCodeTo:100050,
 identicalPublicTestSigner:true,signerSha256:sig,
 actualAndroidPackageManagerInstallOver:true,uninstalledOrCleared:false,
 androidAppPrivateFileCanaryPreserved:true,
 actualAndroidWebViewFiveRecordsPreserved:true,
 baselineRelaunchControlPassed:true,postUpgradeDossierVisible:true,
 sameOriginBrowserSixRecordSeparateGate:'M12-F2',
 rawRecordSha256:Object.fromEntries(savedKeys.map(k=>[k,crypto.createHash('sha256')
  .update(before.keys[k]).digest('hex')])),
 packageSourceSeparation:'M12 test art excluded from both .preview packages',
 physicalOwnerPhoneVerified:false,
 productionSignerVerified:false,
 ordinaryGameInstallerUpgradeVerified:false,
 warning:'AOSP public test signer is only suitable for throwaway emulator .preview APKs; not a stable player upgrade or Play upload key. No owner data was accessed.'
};
fs.mkdirSync('qa-results/m12/release-gate',{recursive:true});
fs.writeFileSync('qa-results/m12/release-gate/m12-f3-android-upgrade.json',
 JSON.stringify(report,null,2)+'\n');
console.log('M12_F3_ANDROID_EMULATOR_INSTALL_OVER_PASS '+JSON.stringify({
 versionFrom:100041,versionTo:100050,records:5,
 canaryPreserved:true,signerMatches:true,releaseApproved:false
}));
